  'task.mode.premium': 'Premium',
  'settings.about.title': 'KnightLoader hakkında',
  'settings.about.body': 'Tek şövalye, tek sefer: istediğim biçimde var olmayan, düzgün görünen açık kaynak araçlar, hiçbir şey eksik kalmayana kadar inşa ediliyor. Hepsi ücretsiz, hesap yok, telemetri yok, reklam yok, ücretli katman yok. Hiçbir yerde yıldız işareti yok. Okunabilir hiçbir şey kendi duvarlarından dışarı çıkmaz. Akşamları ve hafta sonları, yürekle ve inatla dövüldü.',
