  'settings.access.relay.leadProject': 'Hiçbir ayar yapmadan çalışır. Örneklerinin birbirine söylediği her şey şifrelidir ve anahtar yalnızca sende.',
  'settings.access.relay.seesButton': 'Ne görüyor?',
  'settings.access.relay.seesTip': 'Aktarıcının görmediği: bağlantıların, indirmelerin, dosyaların ve erişim jetonun.\n\nAktarıcının gördüğü: örneklerinin IP adresleri ve ne zaman bir şey gönderdikleri.\n\nBu şifrelenerek gizlenemez. Rahatsız ediyorsa kendi aktarıcını çalıştır.',
