  'settings.access.phrase.howStep2': 'Diğer makinede KnightLoader’ı aç, bu aynı sayfaya gel, "{button}" düğmesine bas ve on iki kelimeyi yaz.',
  'settings.access.phrase.howStep3': 'Bitti! Her örnek artık diğerinde „Örnekler“ altında görünür ve hangisini olursa hangisinden olursa yönetebilirsin. Aktarıcı açıkken örneklerine ağının dışından da erişilebilir.',
  'settings.access.phrase.howWhat': 'Kelimeler bir sırdır, adres değil. Her örnek onlardan iki anahtar çıkarır: biri diğerlerini bulmak, biri şifrelemek için.\n\nBirbirlerini bulmak için her örnek kendiliğinden internetteki aynı buluşma noktasını arar. Aynı anahtarı gösteren bağlanır. Bu yüzden örneklerinden hiçbirinin dışarıdan erişilebilir olması gerekmez.\n\nBuluşma noktası okuyamaz. Kelimelerini asla görmez ve içinden geçen her şey ikinci anahtarla şifrelidir.',
