  'onboarding.welcome.body': 'KnightLoader, kendi sunucunda çalışan bir indirme yöneticisidir. Bir bağlantı yapıştır ya da bırak, uygun arka uç onu getirir: düz dosya bağlantıları için yerleşik motor, medya sayfaları için yt-dlp, zaten ücretini ödediğin hoster\'lar için bir debrid hizmeti ya da geri kalan her şey için headless bir JDownloader. Bu kısa tur, başlamadan önce bakmaya değer tek ayarı gösteriyor.',
