  'settings.rules.action.category': 'Kategori',
  'settings.rules.action.categoryHint': 'Uyan bağlantıları, bu sayfanın aşağısındaki Kategoriler listesinden bir çekmeceye koyar; o çekmece de kendi klasörünü, kuyruktaki yerini, ayıklama anahtarını ve çakışma kuralını birlikte getirir. Değiştirilmeden bırakılırsa hiçbir kuralın bu konuda bir görüşü olmaz ve bağlantı hiçbir yere konmaz. Bu kural ayrıca bir indirme klasörü de belirtiyorsa o klasör kazanır, geri kalan her şeyi yine çekmece verir. Silinmiş bir çekmeceyi belirtmek kaydederken reddedilir, çünkü var olmayan bir çekmeceyi gösteren bir kural, uyduğu her bağlantıda hiçbir şey yapmaz, hem de hiçbir ileti olmadan.',
