  'volume.unsizedHint': 'Bu indirmelerin {n} tanesinde hoster hiç boyut bildirmedi. Toplama hiçbir şey eklemezler, yani gerçek değer burada çizilenden yüksektir.',
  'volume.trimmedHint': 'Geçmiş kendi sınırına dayandı, bu yüzden en eski kaydından öncesi bu eğride de yok. Daha geriye bakmak istiyorsan bu sayfadaki geçmiş sınırını yükselt.',
  'volume.meter': 'Hacim',
  'volume.meterHint': 'Sayaç en son yeniden başladığından beri inmesi biten miktar, İndirmeler ayar sayfasındaki üst sınıra göre ölçülür. Sayı, bir indirme çalışırken değil, bittiğinde değişir. İndirme geçmişinden toplanır, bu yüzden o geçmişi boşaltmak bu sayacı da sıfıra çeker.',
