  'idleAction.problem.suspendRefused': 'Sistem uyku moduna geçmeyi reddetti. Linux üzerinde bunun nedeni genelde yetki yöneticisinin, bu uygulamanın veremeyeceği bir onay istemesidir: kullanıcına uyku iznini ver, ya da “Bir komut çalıştır” seçeneğine geç ve makineyi kendi betiğinle uyut.',
  'idleAction.runFailed': 'Komut başlatılamadı.',
