  'settings.transfer.cardTitle': 'Yedekleme ve aktarım',
  'settings.transfer.cardHint': 'Her iki dosya da burada yazılır ve tarayıcın kaydeder, başka hiçbir yere gitmez. İkisi de debrid ve hoster girişlerini, başlık profillerini, captcha anahtarlarını, bu arayüzün giriş parolasını ya da betiklerini taşımaz: bunlar settings.json dışında şifreli durur, arşiv de onları burada bırakır, yani onları yeni makinede yeniden kurarsın.',
  'settings.transfer.archiveLabel': 'Kurulumun tamamı',
  'settings.transfer.archiveText': 'Bu makinedeki her şeyi içeren tek bir arşiv: veritabanı, indirme listesi, geçmiş ve ayarlar, parolalar dahil, bu yüzden dosyayı özel bir yerde sakla. Geri yükleme bunların tamamının yerini alır ve bir sonraki açılışta geçerli olur.',
  'settings.transfer.settingsLabel': 'Yalnızca ayarlar',
  'settings.transfer.settingsText': 'Yalnızca settings.json: kuyruk sınırları, klasörler, kurallar, kategoriler ve zaman çizelgesi. İçe aktarırken önce her anahtarı görürsün, yalnızca işaretlediğin yazılır ve yeniden başlatmadan hemen geçerli olur.',
  'settings.transfer.export': 'Ayarları dışa aktar',
  'settings.transfer.import': 'Ayarları içe aktar',
  'settings.transfer.withSecrets': 'Kayıtlı parolaları da al',
  'settings.transfer.withSecretsHint': 'Açık: dosya yönlendirici parolasını, her vekil parolasını ve her arşiv parolasını düz metin olarak taşır. Kapalı: bu alanlar öteki makineye boş gelir, sen de bir kez yazarsın. İki durumda da bir sır, buradaki hiçbir şeyin tanımadığı bir yerde duruyor olabilir: içinde API anahtarı bulunan bir feed adresi ya da bir yeniden bağlanma betiğine yazdığın bir parola.',
  'settings.transfer.previewTitle': 'Ne devralınsın?',
