  'settings.mediahook.hint': 'KnightLoader\'ın, bir paketin son dosyası gelip yerine taşındıktan sonra bir kez çağırdığı adres. Jellyfin ya da Plex üzerinde bir kitaplık taraması için düşünülmüştür, ama alanın ikisinden de haberi yoktur: yazdığın adresi, seçtiğin yöntemle çağırır ve bir tane verirsen bir başlık ekler. Başlık değeri, hesap girişlerinle aynı şifreli depoda mühürlü durur ve bu sayfaya asla geri gelmez. Bir adres kaydedip onu Kurallar ve kategoriler altında bir çekmecede seçmediğin sürece hiçbir şey çağrılmaz. Paket adı olmayan bir indirme hiçbir zaman çağrı tetiklemez, çünkü son dosyası olabileceği bir paket yoktur. Sunucu yeniden başlarken biten bir paket için de çağrı yapılmaz: ilk tur neyin zaten bitmiş olduğunu yazar ve bunu duyurmaz.',
  'settings.mediahook.empty': 'Henüz adres kaydedilmedi.',
  'settings.mediahook.emptyHint': 'Medya sunucun yeni dosyaları kendiliğinden fark etmiyorsa bir tanesi işe yarar.',
  'settings.mediahook.add': 'Adres ekle',
  'settings.mediahook.name': 'Ad',
  'settings.mediahook.nameHint': 'Bu adresi Kurallar ve kategoriler altında bir çekmecede bu adla seçersin. Yalnızca harfler, rakamlar ve - _ ya da . Sonradan değiştirilemez, çünkü bir çekmece ona bu adla işaret eder.',
  'settings.mediahook.url': 'Adres',
  'settings.mediahook.urlHint': 'Çağrılacak tam adres, http ya da https, host ve port dahil. Kaydetmeden önce bir kez daha oku: burada ne yazıyorsa bu makineden çağrılır. Adresin kendisi settings.json içinde düz metin olarak durur ve tanılama paketine de gider, o yüzden bir tokeni adresin sorgu bölümüne değil, aşağıdaki başlığa yaz.',
  'settings.mediahook.method': 'Yöntem',
  'settings.mediahook.methodHint': 'GET ya da POST. POST, gövdesi olmadan gönderilir. Jellyfin POST ister, Plex GET ister, emin değilsen sınama çağrısı karşı tarafın hangisini kabul ettiğini söyler.',
  'settings.mediahook.headerName': 'Başlık adı',
  'settings.mediahook.headerNameHint': 'Çağrıyla birlikte giden tek başlık, örneğin Jellyfin için X-Emby-Token. Ek başlık göndermemek için boş bırak.',
  'settings.mediahook.headerValue': 'Başlık değeri',
  'settings.mediahook.headerValueHint': 'O başlığa girecek token. Hesap girişlerinle aynı şifreli depoda mühürlü durur, settings.json içine hiç yazılmaz ve bu sayfaya asla geri gönderilmez.',
  'settings.mediahook.valueStored': 'Kayıtlı',
  'settings.mediahook.valueStoredHint': 'Değer bu örnekte kalır. Korumak için alanı olduğu gibi bırak, değiştirmek için yenisini yaz. Alanı boşaltırsan değer silinir.',
  'settings.mediahook.goesTo': 'Çağrı {host} adresine gidiyor',
  'settings.mediahook.goesToForeign': 'Bu adres senin kendi ağında değil. Çağrı bu makineden çıkar, başlık da onunla birlikte gider.',
  'settings.mediahook.wait': 'Çağrıdan önce bekleme',
  'settings.mediahook.waitHint': 'Bir paket bittikten sonra bu adresin ne kadar rahat bırakılacağı, böylece aynı anda biten yirmi paketten yirmi çağrı değil tek bir çağrı çıkar. Bir kitaplık taraması medya sunucusuna gerçek iş çıkarır, bir dakika sonra gelen bir tanesi ise sana hiçbir şeye mal olmaz. 0 yapıldığında çağrı, bir paketin dosyaları yerine yerleşir yerleşmez, başkalarını beklemeden yola çıkar.',
  'settings.mediahook.waitImmediate': 'Çağrı, bir paket hazır olur olmaz, başkalarını beklemeden yola çıkar.',
  'settings.mediahook.error.nameInvalid': 'Bir ad yalnızca harf, rakam ve - _ ya da . içerir, en fazla 64 karakter.',
  'settings.mediahook.save': 'Adresi kaydet',
  'settings.mediahook.delete': 'Adresi sil',
  'settings.mediahook.deleteConfirm': '{name} silinsin mi? Kayıtlı başlık değeri de onunla gider ve bu sayfadan geri getirilemez.',
  'settings.mediahook.deleteInUse': '{name} hâlâ {n} çekmecede seçili. Önce onları “Hiçbir şeyi tetikleme” yap, sonra sil.',
  'settings.mediahook.usedBy': '{n} çekmecede seçili',
  'settings.mediahook.usedByNone': 'Kayıtlı, henüz onu çağıran bir şey yok',
  'settings.mediahook.test': 'Sınama çağrısı gönder',
