  'settings.mediahook.lastCall': 'Son çağrı',
  'settings.mediahook.lastCallHint': 'Bu adresin en son çağrılışında ne olduğu, sınama çağrıları da sayılır. Yalnızca bellekte tutulur, yani bir yeniden başlatma onu siler ve adresin kendisinde hiçbir şeyi değiştirmez.',
  'settings.mediahook.lastCallNever': 'Bu sunucu başladığından beri çağrılmadı',
  'settings.mediahook.answeredAfter': '{duration} sonra {status} yanıtı verdi',
  'settings.mediahook.failedAfter': '{duration} sonra başarısız oldu',
  'settings.mediahook.lastCallFor': '{name} paketi için',
  'settings.mediahook.lastCallTest': 'Sınama çağrısı',
