  'settings.eventTargets.problem.dns': 'Host, bu örneğin içinden çözülemedi. Bir konteynerin çoğu zaman kendi ad hizmeti olur, yani kendi bilgisayarının ulaştığı bir adrese bu makine kendiliğinden ulaşmaz.',
  'settings.eventTargets.problem.refused': 'Orada hiçbir şey dinlemiyor. Portu ve hizmetin gerçekten çalışıp çalışmadığını denetle.',
  'settings.eventTargets.problem.tls': 'Sertifika kabul edilmedi. Bunun olağan nedeni, kendi sunucunda kendinden imzalı bir sertifikadır. Kendi ağında http kullan, ya da bu konteynere sertifikayı ver.',
