  'settings.eventTargets.problem.auth': 'Karşı taraf kimlik bilgilerini reddetti. Başlıklardaki tokeni denetle, bir de başka bir hosta giden bir yönlendirmenin Authorization başlığını yolda attığını unutma.',
  'settings.eventTargets.problem.notFound': 'Karşı taraf bu yolu tanımıyor. ntfy için konu adrese girer, Matrix için oda kimliği girer.',
