  'settings.eventTargets.problem.rateLimited': 'Karşı taraf şimdilik reddediyor, çünkü bir anda çok fazla şey vardı. Daha gürültülü olayların işaretini kaldır, ya da genel bir sunucu yerine kendi sunucuna gönder.',
