  'settings.module.metrics': 'Bir izleme sistemi için ölçüm adresi',
  'settings.health.title': 'Şu andaki durum',
  'settings.health.titleHint': 'Bu sayfa yalnızca okur. Üzerindeki hiçbir şey bir şeyi başlatmaz, durdurmaz ya da değiştirmez, sayfayı açık bırakman da bir şeyi değiştirmez. Değerler on saniyede bir alınır; başarısız bir alım, sayfayı boşaltmak yerine son okumayı yerinde bırakır. Yoklanması gereken bileşenler yarım dakika boyunca paylaşılır, yani burada gördüğün, İndirmeler sayfasındaki satırların otuz saniyeye kadar gerisinde olabilir.',
  'settings.health.version': 'Sürüm',
  'settings.health.uptime': 'Çalışma süresi',
  'settings.health.uptimeHint': 'Bu sürecin ne kadar süredir çalıştığı, makinenin ne kadar süredir çalıştığı değil. Bir saat önce yeniden başlamış bir konteyner, ana makine ne derse desin burada yine sıfırdan başlar. Yanındaki tarih sunucunun kendi saatidir, tarayıcının saati değil.',
  'settings.health.startedAt': 'Başladığı an',
