  'settings.health.oldHealthHint': 'Eski adres /api/health değişmedi ve bu sayfa ne derse desin, bu işlem çalıştığı sürece “ok” yanıtını vermeye devam eder. Böyle kalır, çünkü konteynerin kendi sağlık denetimi, Click\'n\'Load köprüsü ve telefon uygulamasının ağındaki örnekleri araması onu okur; orada “ok” dışında bir yanıt konteyneri sağlıksız olarak işaretler ve telefonun bu örneği bulmasını durdururdu. Arızalar bu sayfada bildirilir; o adres yalnızca dinleyen bir şey olup olmadığını söyler.',
