  'health.remedy.store.failed': 'Veritabanı yanıt vermedi. İndirmeler çalışmayı sürdürür, ama artık onlarla ilgili hiçbir şey yazılmıyor, yani bir yeniden başlatma o andan beri değişen her şeyi kaybederdi. Veri klasörünün hâlâ bağlı ve hâlâ yazılabilir olduğuna bak.',
  'health.remedy.jd.unreachable': 'KL_JD, bu örneğin şu anda erişemediği bir adresi gösteriyor. JDownloader konteynerinin çalıştığına ve API portunun buradan yanıt verdiğine bak. Yalnızca JDownloader\'ın çekebildiği bağlantılar o sürece kuyrukta kalır, başarısız olmuş sayılmazlar.',
  'health.remedy.jd.notWired': 'JDownloader yeniden yanıt veriyor, ama bu süreç arka uçlarını açılışta bağladı ve o sırada onu bulamadı. Devralınması için KnightLoader\'ı yeniden başlat.',
  'health.remedy.ytdlp.missing': 'Bu süreç başladığında hiçbir yt-dlp bulunamadı (KL_YTDLP ya da PATH üzerinde “yt-dlp”). Medya sayfaları o zaman varyantlara açılmak yerine sitenin kendi hatasıyla başarısız olur. Bulunabilmesi için yeniden başlatmak gerekir.',
  'health.remedy.disk.low': 'Bir hedef klasör, İndirmeler sayfasında koyduğun alt sınırın altında. Yeniden yer açılana ya da sen alt sınırı düşürene kadar orada yeni bir şey başlamaz. Çalışmakta olan, bu alt sınır yüzünden durdurulmaz.',
  'health.remedy.disk.elsewhere': 'Bir klasör yerinde değil, bu yüzden sayılar onun üstündeki en yakın klasörü anlatıyor. Bir bağlama yukarı gelmediyse o bambaşka bir disktir. Sayılara inanmadan önce yola bak.',
  'health.remedy.accounts.benched': 'En az bir hoster hesabı, bir hatadan sonra rahat bırakılıyor. Bekleme bittiğinde kendiliğinden bir kez daha denenir, bekleme de her seferinde ikiye katlanır. Şimdi bilmek istiyorsan Hesaplar sayfasına git ve satırdaki Yenile düğmesine bas.',
  'health.remedy.accounts.invalid': 'En az bir hoster hesabı reddedildi. Yeni bir anahtar ya da yenilenmiş bir abonelik bunu düzeltir, beklemek düzeltmez.',
  'health.remedy.feeds.failing': 'En az bir aboneliğin son alımı başarısız oldu. Hangisi ve neden, İndirmeler sayfasında feedin yanında ve Tanılama sayfasındaki günlük satırlarında yazar.',
  'health.remedy.relay.down': 'Bir aktarıcı adresi kayıtlı ve bağlantı kurulu değil. Bu örnek kendiliğinden denemeyi sürdürür ve yereldeki her şey her zamanki gibi işler, yalnızca dışarıdan erişim işlemez.',
  'health.remedy.captcha.waiting': 'Bir arka uç durup bir insana soruyor. Biri yanıtlayana kadar arkasında hiçbir şey ilerlemez.',
  'settings.health.tasks': 'Şu andaki indirmeler',
  'settings.health.tasksHint': 'Listenin şu anki hâlinin anlık görüntüsü, zaman içindeki bir sayım değil, bu yüzden bu sayıların hiçbiri bir şeyin ne sıklıkla başarısız olduğunu söylemez. “Başarısız”, listede üzerinde hata olan satırları sayar: onları temizlediğinde ve liste ayarladığın gün sayısından sonra toparlandığında düşer, yeni bir şey ters gittiğinde yeniden yükselir.',
  'settings.health.diskWhere': 'Hedef klasörlerde ne kadar yer olduğunu İndirmeler sayfası gösterir.',
