  'settings.health.nothingWaiting': 'Hiçbir şey bekletilmiyor.',
  'settings.health.nothingFailed': 'Listede başarısız olan bir şey yok.',
  'settings.health.scrapeHint': 'Aynı değerleri düz metin olarak, Prometheus ile onun gibi kurulmuş araçların okuduğu biçimde veren ikinci bir adres açar. O adres çekilir, hiçbir zaman gönderilmez: senin kendi izlemen buraya gelip istemedikçe bu makineden hiçbir şey çıkmaz. Bu kapalı olduğu sürece adres hiç yoktur ve bu uygulamanın sahip olmadığı başka her adres gibi 404 yanıtı verir. Parolalı bir örnekte çekim, API tokenlerinden birini gerektirir ve bunu her toplayıcıya öğretebilirsin. Bir toplayıcı köken başlığı göndermez, bu yüzden geçer; başka bir adresteki bir tarayıcı sekmesi ise gönderir ve bu örneğin kendi adresine uymuyorsa reddedilir. Metinde hedef klasörlerinin yolları yazar, yani onu ancak klasör adlarının kendisini vereceğin yere ver.',
  'settings.health.scrapeUrl': 'Ölçüm adresi',
  'settings.health.scrapeCopy': 'Adresi kopyala',
