  'settings.owner.fix.mask': 'Bunu bu örnek değiştiremez. Maske, konteyneri her ne başlattıysa ondan gelir, bağlı bir paylaşım da umask, file_mode ya da dir_mode seçeneğiyle kendi maskesini zorlayabilir. Bunu klasörün bağlandığı yerde düzelt.',
  'settings.owner.fix.recreate': 'Değişmiş bir başlatma komutu için konteynerin yeniden oluşturulması gerekir. Yeniden başlatmak yetmez: kimlik, konteyner başladığı anda sabitlenir.',
