  'settings.selftest.accounts.advice.error': 'Sağlayıcı, ne yeni bir anahtarın ne de beklemenin çözeceği bir şey söylüyor, örneğin adresine konmuş bir engel.',
  'settings.selftest.accounts.readOnlyHint': 'Bu denetim dağıtımda hiçbir şeyi değiştirmez. Burada başarısız olan bir giriş bildirilir, kenara alınmaz: hattın kopmuşken yapılan bir öz sınama, her hesabı sonraki çeyrek saat boyunca felç etmemelidir.',
  'settings.selftest.relay': 'Aktarıcı',
