  'settings.selftest.relay.notSetUp': 'Uzaktan erişim burada hiç kurulmamış, yani hiçbir aktarıcı aranmaz.',
  'settings.selftest.relay.ownNoAddress': 'Kendi aktarıcın seçili ve bir adres ayarlanmamış, yani hiçbir yer aranmaz.',
