  'settings.selftest.relay.notConnectedAdvice': 'Ya aktarıcıya şu anda erişilemiyor, ya da anahtarı reddetti. Kendiliğinden denemeyi sürdürür. Hiç kurulamıyorsa adresi denetle ve bağlantı cümlesini yeniden gir.',
  'settings.selftest.clock': 'Saat ve zaman dilimi',
  'settings.selftest.clock.ok': 'Bu makine {time} diyor, dilim {zone}.',
  'settings.selftest.clock.skew': 'Bu makine ile tarayıcın arasında {skew} fark var.',
  'settings.selftest.clock.skewAdvice': 'İkisinden biri yanlış gidiyor ve bu uygulama hangisi olduğunu söyleyemez. Bu kadar sapmış bir saat, TLS sertifikalarını geçersiz gösterir ve debrid tokenlerinin reddedilmesine yol açar. Önce ana makinenin saatine bak, konteyner zamanını oradan alır.',
  'settings.selftest.clock.utc': 'Zaman dilimi UTC ve senin kurulu bir zaman çizelgen var.',
  'settings.selftest.clock.utcAdvice': 'Zaman çizelgesi bu makinenin yerel saatine göre işler, TZ ayarlı değilken de o saat UTC olur. Saat 22:00 için koyduğun bir pencere o zaman UTC ile 22:00 başlar, bu da Berlin için kışın 23:00, yazın gece yarısı demektir. Konteyneri TZ ile başlat, örneğin TZ=Europe/Berlin, sonra onu yeniden başlat.',
  'settings.selftest.clock.noZoneDB': 'TZ, {zone} diliminden söz ediyor ve zaman dilimi veritabanı okunamadı, bu yüzden bu süreçteki her zaman değeri UTC değerine geri düşüyor.',
  'settings.selftest.torrentPort': 'Torrent portu',
  'settings.selftest.torrentPort.noPort': 'Torrent motoru portunu kendi seçiyor ve bu yapı hangisini aldığını geri okuyamıyor.',
  'settings.selftest.torrentPort.noPortAdvice': 'Torrentler sayfasında sabit bir port belirle. O olmadan yönlendirilecek bir şey de denetlenecek bir şey de yoktur, başka bir yönlendiricinin arkasındaki eşler de sana ancak önce kendileri bağlandığında ulaşır.',
  'settings.selftest.torrentPort.notChecked': 'Port {port} ayarlı. Bu ağın dışındaki hiçbir şeye sorulmadı, bu yüzden dışarıdan açık olup olmadığı bilinmiyor.',
  'settings.selftest.torrentPort.notCheckedAdvice': 'Bunu yalnızca kendi ağının dışındaki bir makine yanıtlayabilir ve bu uygulama senin seçmediğin hiçbir makineyle bağlantı kurmaz. Torrentler sayfasındaki UPnP düğmesi yönlendiricinden portu yönlendirmesini ister ve bunu doğrulayıp doğrulayamadığını söyler. Bu çalışmanın ilk torrentinden sonra kaydedilen bir port ancak yeniden başlatmadan sonra geçerli olur.',
  'settings.selftest.proxy.title': 'Ters vekil',
  'settings.selftest.proxy.hint': 'Tarayıcının ve bu örneğin, tam olarak aynı istek hakkında ne söylediği. Bu dördü, Nginx Proxy Manager ile Traefik arkasında ters giden şeylerdir, dördünden üçü de hiçbir hata iletisi olmadan çuvallar.',
  'settings.selftest.proxy.desktopSkip': 'Masaüstü sürümü kendi arayüzünü kendi sunar ve önünde bir vekil yoktur, yani burada karşılaştırılacak bir şey de yoktur.',
  'settings.selftest.proxy.host': 'Host başlığı',
  'settings.selftest.proxy.host.ok': 'Tarayıcın ile bu örnek, hostun {host} olduğunda anlaşıyor.',
  'settings.selftest.proxy.host.rewritten': 'Tarayıcın {browser} istedi, bu örneğe ise {server} söylendi.',
  'settings.selftest.proxy.host.rewrittenAdvice': 'Vekilin Host başlığını değiştiriyor. Bu örnek tarayıcının Origin değerini Host ile karşılaştırır, bu yüzden her yazma 403 ile reddedilir ve canlı görünüm hiç açılmaz, sayfanın kendisi ise yüklenmeyi sürdürür ve iyi görünür. Traefik üzerinde passHostHeader açık kalsın. nginx üzerinde proxy_set_header Host $host kullan.',
  'settings.selftest.proxy.proto': 'İletilen protokol',
  'settings.selftest.proxy.proto.ok': 'Vekil https diyor, tarayıcın da tam olarak onun üzerinde.',
  'settings.selftest.proxy.proto.direct': 'Bu örneğe doğrudan ulaştın, yani bir şey bildirmesi gereken bir vekil yok.',
  'settings.selftest.proxy.proto.missing': 'Tarayıcın https üzerinde ve vekil bunu iletmedi.',
  'settings.selftest.proxy.proto.missingAdvice': 'X-Forwarded-Proto olmadan bu örnek, kendisine düz http üzerinden ulaşıldığını sanır. O zaman Uzaktan erişim sayfasındaki QR kodu ve eşleştirme adresleri http:// bağlantıları sunar, JDownloader’a verilen bir konteyner de http üzerinden alınır. nginx üzerinde proxy_set_header X-Forwarded-Proto $scheme; kullan. Traefik ile Caddy bunu kendileri ayarlar.',
  'settings.selftest.proxy.prefix': 'Yol öneki',
  'settings.selftest.proxy.prefix.underPath': 'Bu örnek {path} altında sunuluyor.',
  'settings.selftest.proxy.ws': 'WebSocket yükseltmesi',
  'settings.selftest.proxy.ws.ok': 'Canlı bağlantı kuruldu.',
  'settings.selftest.proxy.ws.failed': 'Canlı bağlantı kurulmadı.',
  'settings.selftest.proxy.ws.failedAdvice': 'Bir vekil arkasında en sık görülen arıza budur ve başka hiçbir şey onu sana göstermez: uygulama sessizce tekrar tekrar bağlanır, liste öylece durur ve yalnızca sayfayı yeniden yüklemek yeni bir şey gösterir. nginx üzerinde location bloğu proxy_http_version 1.1, proxy_set_header Upgrade $http_upgrade ve proxy_set_header Connection "upgrade" satırlarını ister. Nginx Proxy Manager, hostun üzerinde bir Websockets Support anahtarı sunar. Traefik ile Caddy için bir şey gerekmez.',
  'settings.diagnostics.startupTitle': 'Açılış raporu',
  'settings.diagnostics.startupHint': 'Bu örneğin başlarken bir kez denetlediği şeyler: çağırdığı programlar, bir indirmenin düşebileceği her klasör ve zamanlamaların dayandığı saat. Bu bir ölçümdür, bu yüzden buradaki hiçbir şey bir indirmeyi geri tutmaz ya da sunucunun açılmasını engellemez. Başlangıçta yalnızca bakılır; yazma denemesi “Yeniden denetle”ye bastığında yapılır.',
  'settings.diagnostics.startupTakenAt': '{when} saatinde, bu örnek açıldıktan hemen sonra denetlendi.',
  'settings.diagnostics.startupJustChecked': 'Az önce denetlendi. İndirdiğin paket yine açılışta alınan okumayı taşır, çünkü bir hata raporunun ihtiyacı olan o okumadır.',
  'settings.diagnostics.startupRunning': 'Hâlâ denetleniyor. Yanıt vermeyi bırakmış bir paylaşımdaki bir klasör, o paylaşımın pes etmesi ne kadar sürüyorsa o kadar sürer.',
  'settings.diagnostics.startupOff': 'Denetim bu örnek için kapatılmış (KL_STARTUP_CHECK=0). Hiçbir şeye bakılmadı, bu da “her şey yolunda” ile aynı şey değil.',
  'settings.diagnostics.startupNotRun': 'Bu yapı denetimi hiç çalıştırmadı. Denetim sunucuda ve masaüstü uygulamasında çalışır.',
  'settings.diagnostics.startupStatOnly': 'Açılışta yalnızca bakıldı: hiçbir klasöre bir şey yazılmadı. Yani “Sorun yok” işaretli bir klasör, var olan bir klasördür, bu örneğin içine yazdığı bir klasör değil.',
  'settings.diagnostics.startupNothingWrong': 'Burada yapılacak bir şey yok.',
  'settings.diagnostics.startupRecheck': 'Yeniden denetle',
  'settings.diagnostics.startupRechecking': 'Denetleniyor…',
  'settings.diagnostics.startupRecheckHint': 'Aynı denetimleri şimdi yapar ve bu kez var olan her klasöre küçük bir sınama dosyası yazar, sonra onu yeniden siler. Açılışta bu yapılmaz, çünkü dizideki bir klasöre yazmak, o klasörün üzerinde olduğu diski uyandırır ve bu her yeniden başlatmada olurdu. İndirdiğin paket, açılışta alınan okumayı korur, çünkü bir hata raporunun ihtiyacı olan o okumadır.',
  'settings.diagnostics.startupRecheckFailed': 'Yeniden denetlenemedi: {error}',
