  'settings.diagnostics.fix.missing': 'Klasör yok. Üstünde var olan en yakın klasör {measured}. Bir paylaşımı bağlayan bir makinede bu genelde paylaşımın bağlı olmadığı anlamına gelir; bu denetimin klasörü oluşturmamasının nedeni de bu: eksik bir bağlama noktasının altında açılan bir klasör indirmeleri üstlenir ve onlar bir sonraki konteyner güncellemesinde kaybolur.',
  'settings.diagnostics.fix.denied': 'Klasör yerinde ve bu örnek içine yazamıyor. Konteynerde KnightLoader uid 1000 olarak çalışır, yani klasör bu kullanıcıya ya da onun içinde olduğu bir gruba ait olmalı.',
  'settings.diagnostics.fix.readonly': 'Bu klasörün altındaki dosya sistemi yalnızca okunur olarak bağlanmış. Bunu bu örneğin yaptığı hiçbir şey değiştirmez, bağlamanın değişmesi gerekir.',
  'settings.diagnostics.fix.full': 'Bu klasörün üzerinde olduğu birimde hiç yer kalmadı.',
