  'settings.diagnostics.fix.notADir': 'Bu yolda bir dosya var, klasör değil.',
  'settings.diagnostics.fix.timeout': 'Klasör zamanında yanıt vermedi ve rahat bırakıldı. Sunucusu kapalı bir paylaşım tam böyle davranır, ortadan kaybolmuş bir ağdaki bir paylaşım da öyle.',
  'settings.diagnostics.fix.dataDenied': 'Bu, örneğin olmadan yapamadığı tek klasör: veritabanı, ayarlar ve şifreli hesap deposu burada durur. İndirmeler şimdilik çalışmayı sürdürür, kaydettiğin bir sonraki şey ise kaybolur.',
  'settings.diagnostics.fix.javaMissing': 'Java bulunamadı. Kapsayıcı imajında bir tane var ama masaüstü uygulamasında yok, bu yüzden masaüstünde Java’nın PATH’te veya JAVA_HOME altında kurulu olması gerekir. Onsuz özel JDownloader başlamaz ve şifreli bir kapsayıcı bağlantısı (.dlc, .ccf, .rsdf) hiç açılamaz. Java’yı kur veya KL_JD’yi başka yerde çalışan bir JDownloader’a yönlendir.',
  'settings.diagnostics.fix.javaNotNeeded': 'Bu örnek kendine ait hiçbir Java süreci başlatmıyor: ya KL_JD başka bir yerde çalışan bir JDownloader\'ı gösteriyor, ya da özel olan KL_PROVISION_JD=0 ile kapatılmış.',
  'settings.diagnostics.fix.ytdlpMissing': 'yt-dlp bulunamadı (KL_YTDLP ya da PATH üzerinde “yt-dlp”). Medya sayfaları o zaman indirilmek yerine sitenin kendi hatasıyla başarısız olur.',
  'settings.diagnostics.fix.ffmpegMissing': 'ffmpeg bulunamadı. yt-dlp, çoğu sitenin ayrı ayrı verdiği görüntü ve ses akışlarını birleştirmek için ona ihtiyaç duyar, yani bir indirme ikisinden birinde takılır ya da sessiz geri döner.',
  'settings.diagnostics.fix.ffprobeMissing': 'ffprobe bulunamadı. Onu yalnızca bitmiş bir videonun uzunluk denetimi kullanır, geri kalan her şey onsuz işler.',
  'settings.diagnostics.fix.notRunnable': '{subject} yolunda bulundu ve çalışmadı: {error}',
  'settings.diagnostics.fix.appearedLate': 'Şimdi çalışıyor, bu örnek başladığında ise yerinde değildi, yani ona henüz hiçbir şey yönlendirilmiyor. Devralınması için yeniden başlat.',
  'settings.diagnostics.fix.utcFallback': 'TZ değeri {subject} olarak ayarlı ve bu örnek o dilimi yükleyemedi, bu yüzden hiçbir yerde bunu söylemeden UTC değerine geri düştü. Bu düzeltilene kadar her zaman çizelgesi penceresi UTC üzerinde işler. Yazımı dilim listesiyle karşılaştır (“Europe/Berlin”), bir de imajın gerçekten bir dilim veritabanı olup olmadığına bak.',
  'settings.diagnostics.fix.noZoneDatabase': 'Bu sistemde dilim veritabanı yok, yani saatler hiçbir yaz saati geçişi olmadan okunur. Gecelik bir pencere kış saatini bütün yaz boyunca korur ve o an geldiğinde kimse bunu haber vermez.',
  'settings.diagnostics.fix.tzUnset': 'TZ ayarlı değil ve yerel saat bulunamadı, bu yüzden bu örnek UTC ile çalışıyor. Bu işe yarar, ama o zaman 23:00 olarak yazılmış bir zamanlama penceresi, bulunduğun yerde 23:00 değil, UTC ile 23:00 demektir.',
  'settings.resolvers.toolsTitle': 'Araçlar',
  'settings.resolvers.toolsHint': 'yt-dlp medya sayfasını okur, ffmpeg de ondan geri gelen akışları birleştirir. İkisi de KnightLoader\'ın başlattığı ayrı programlardır ve hiçbiri bu yapının parçası değildir, bu yüzden sürümleri bilmeye değer: güncelliğini yitirmiş bir yt-dlp, geçen ay çalışan bir medya bağlantısının artık çalışmamasının en sık nedenidir.',
  'settings.resolvers.toolsInUse': 'Kullanımda',
  'settings.resolvers.toolsNotFound': 'Bulunamadı',
  'settings.resolvers.toolsFrom.managed': 'KnightLoader\'ın kendi kopyası',
  'settings.resolvers.toolsFrom.env': 'KL_YTDLP',
  'settings.resolvers.toolsFrom.path': 'PATH üzerinde bulundu',
  'settings.resolvers.toolsFrom.none': 'Hiçbir yerde',
  'settings.resolvers.toolsYtdlpMissingHint': 'yt-dlp olmadan hiç medya arka ucu olmaz: bir video sayfasına giden bağlantı, indirilmek yerine sitenin kendi hatasıyla reddedilir. Konteynerde imajın yt-dlp paketinden gelir, masaüstünde onu kendin kurarsın ve ya PATH üzerine koyarsın ya da KL_YTDLP değerini ona yönlendirirsin. İkisi de olmuyorsa aşağıdaki düğme kendiliğinden bir kopya getirir.',
  'settings.resolvers.toolsFfmpegMissingHint': 'ffmpeg olmadan yt-dlp, çoğu sitenin ayrı ayrı verdiği görüntü ve ses izlerini birleştiremez, yani bir indirme ya sessiz bir video izi olarak iner ya da baştan başarısız olur. ffprobe olmadan da bu sayfanın yukarısındaki “Bitmiş dosyayı ölç” hiçbir şey ölçmez ve bu konuda bir şey söylemez. Konteynerde ikisi de imajın kurduğu ffmpeg paketinden gelir, masaüstünde onları kendin kurar ve PATH üzerine koyarsın.',
  'settings.resolvers.toolsShadowed': 'KnightLoader\'ın kendi kopyası çalışıyor. O oradayken KL_YTDLP ile PATH başlatılmaz: onların yerine {path} kullanılırdı, o da {version} bildiriyor.',
  'settings.resolvers.toolsShadowedOlder': 'Dikkat: KnightLoader\'ın getirdiği kopya ({current}), bu makinede zaten duran kopyadan ({system}, {path} yolunda) daha eski. Bir konteyner güncellemesi yanında daha yeni bir yt-dlp getirir, senin kendi kopyan ise onunla birlikte ilerlemez. Yeni bir tane getir, ya da sistem kopyasına geri dön.',
  'settings.resolvers.toolsManagedBroken': '{path} yolunda getirilmiş bir kopya kayıtlı ve o başlamıyor. Onun yerine yukarıda gösterilen yedek seçenek çalışıyor. Onu yeniden getir, ya da sistem kopyasına geri dön.',
  'settings.resolvers.toolsActions': 'yt-dlp sürümünü güncel tutmak',
  'settings.resolvers.toolsActionsHint': 'Getirme, yt-dlp dosyasını github.com üzerinden indirir, aynı sürümle birlikte yayımlanan SHA2-256SUMS dosyasıyla karşılaştırır, bu makinede gerçekten çalışıp çalışmadığını görmek için onu bir kez başlatır ve ancak ondan sonra verilerinin yanına, KnightLoader\'ın onu başlattığı yere koyar. O son adıma kadar elinde zaten olan kopya çalışmayı sürdürür ve sisteminin kendi yt-dlp dosyasına hiç dokunulmaz.',
  'settings.resolvers.toolsCheck': 'GitHub\'a sor',
  'settings.resolvers.toolsChecking': 'GitHub\'a soruluyor…',
  'settings.resolvers.toolsFetch': 'Bu sürümü getir',
  'settings.resolvers.toolsFetching': 'Getiriliyor ve denetleniyor…',
  'settings.resolvers.toolsRevert': 'Sistem kopyasına geri dön',
  'settings.resolvers.toolsReverting': 'Kaldırılıyor…',
  'settings.resolvers.toolsSame': '{version} kurulu ve bu, yayımlanmış en yeni sürüm.',
  'settings.resolvers.toolsNewer': 'Yayımlanan {latest}, kurulu olan {current}.',
  'settings.resolvers.toolsOlder': 'Kurulu olan {current} ve bu, yayımlanmış en yeni sürümden ({latest}) daha yeni. Yapılacak bir şey yok.',
  'settings.resolvers.toolsUnknown': 'Yayımlanan {latest}, kurulu olan {current}. Bu ikisinden hangisinin daha yeni olduğu iki sürüm dizgesinden okunamıyor, bu yüzden burada bir şey iddia edilmiyor.',
  'settings.resolvers.toolsCheckFailed': 'GitHub\'a sorulamadı: {error}',
