  'settings.stall.reconnect': 'Durmuş bir indirme için yeni bağlantılar aç',
  'settings.stall.reconnectHint': 'İşaretli bir indirmenin bağlantılarını kapatır ve dosyanın kalanını isteyen yenilerini açar. İndirme zaten aldığını ve yerini korur, bu yüzden sen kapatana kadar açıktır. Dosyayı yalnızca tek parça gönderebilen bir sunucu onu baştan yeniden gönderir. Bu olmadan, sunucusu dosyanın ortasında yanıt vermeyi bırakan bir indirme, biri duraklatana kadar 0 B/s’de bekler. İndirme durduğu sürece, yukarıda ayarlanan süre her dolduğunda bu tekrarlanır. “Durmuş bir indirmeyi baştan başlat” da açıksa, yeni bağlantılardan sonra da o kadar duran bir indirme baştan başlar. Yeni bağlantıları yalnızca yerleşik motorun indirmeleri alır, debrid ve TorBox indirmeleri dahil. JDownloader ve yt-dlp kendi bağlantılarıyla kendileri ilgilenir, eşi olmayan bir torrente de yeni bağlantılar yardımcı olmaz, bu yüzden bunlar yalnızca işaretlenir.',
